sp_widget.script:
(function() { data.templateId = $sp.getParameter("template_id") || ""; data.templateData = {}; data.sections = [];
  try { if (data.templateId) { var gr = new GlideRecord("x_1433041_identi_0_template"); if (gr.get(data.templateId)) { data.templateData = { name: gr.getValue("name"), description: gr.getValue("description"), category: gr.getValue("category"), status: gr.getDisplayValue("status") }; } }
    if (input && input.action === "save") { var tGr = data.templateId ? new GlideRecord("x_1433041_identi_0_template") : null; if (data.templateId && tGr.get(data.templateId)) { tGr.setValue("name", input.name); tGr.setValue("description", input.description || ""); tGr.setValue("category", input.category || ""); tGr.update(); data.saved = true; } else { var nGr = new GlideRecord("x_1433041_identi_0_template"); nGr.initialize(); nGr.setValue("name", input.name); nGr.setValue("description", input.description || ""); nGr.setValue("category", input.category || ""); nGr.setValue("status", "draft"); data.templateId = nGr.insert(); data.saved = true; } }
  } catch (e) { gs.error("IBAR Template Form widget error: " + e.message); }
})();
